import fs from 'node:fs';
import path from 'node:path';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
const dir=path.dirname(fileURLToPath(import.meta.url));
const [name,script,...args]=process.argv.slice(2);
if(!/^[a-z0-9-]+$/.test(name??'')||!script)throw new Error('Explicit unique record name and script required');
const stdoutFile=path.join(dir,name+'.stdout.log'),stderrFile=path.join(dir,name+'.stderr.log');
const out=fs.openSync(stdoutFile,'wx'),err=fs.openSync(stderrFile,'wx');
const startedAt=new Date().toISOString();
let exitCode=null,signal=null;
await new Promise((resolve,reject)=>{
 const child=spawn(process.execPath,[script,...args],{cwd:process.cwd(),shell:false,windowsHide:true,stdio:['ignore','pipe','pipe']});
 child.stdout.on('data',bytes=>{fs.writeSync(out,bytes);process.stdout.write(bytes);});
 child.stderr.on('data',bytes=>{fs.writeSync(err,bytes);process.stderr.write(bytes);});
 child.on('error',reject);
 child.on('close',(code,sig)=>{exitCode=code;signal=sig;resolve();});
});
fs.closeSync(out);fs.closeSync(err);
fs.writeFileSync(path.join(dir,name+'.child-completion.json'),JSON.stringify({startedAt,finishedAt:new Date().toISOString(),executable:process.execPath,script:path.resolve(script),args,cwd:process.cwd(),exitCode,signal,stdoutFile,stderrFile,method:'RAW_BYTES_TO_DISTINCT_WX_LOGS',automaticRetry:false,processTerminationUsed:false},null,2)+'\n',{flag:'wx'});
process.exitCode=exitCode??1;
